<?php
ob_start();session_id('nstAliVoice'.bin2hex(random_bytes(8)));session_start();$_SESSION['user']='superadmin';$cookie='PHPSESSID='.session_id();session_write_close();try{$h=curl_init('http://localhost/api/index.php/ali/config');curl_setopt_array($h,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_COOKIE=>$cookie,CURLOPT_TIMEOUT=>10]);$config=json_decode(curl_exec($h),true);curl_close($h);if(empty($config['csrf']))throw new Exception('No configuration session');$h=curl_init('http://localhost/api/index.php/ali/voz');curl_setopt_array($h,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_COOKIE=>$cookie,CURLOPT_TIMEOUT=>40,CURLOPT_HTTPHEADER=>['Content-Type: application/json','X-Ali-CSRF: '.$config['csrf']],CURLOPT_POSTFIELDS=>json_encode(['text'=>'Hola, soy ALI.','voice'=>'coral'])]);$body=curl_exec($h);$code=curl_getinfo($h,CURLINFO_HTTP_CODE);$type=curl_getinfo($h,CURLINFO_CONTENT_TYPE);curl_close($h);if($code===200&&strpos($type,'audio/mpeg')===0&&strlen($body)>100){file_put_contents(__DIR__.'/../.tmp-order-workbook/ali-coral-test.mp3',$body);echo 'PASS OpenAI Coral speech returned MP3 ('.strlen($body).' bytes). One short greeting generated.'.PHP_EOL;}else{echo 'VOICE CHECK: HTTP '.$code.' '.(json_decode($body,true)['error']??'No audio received').PHP_EOL;}}finally{session_start();$_SESSION=[];session_destroy();ob_end_flush();}
